import numpy as np
D=np.array([list('0000000000'),list('000000000f'),list('00000000ff'),list('0000000fff'),list('000000ffff'),list('00000f0000'),list('00000ff000'),list('00000fff00'),list('00000ffff0'),list('00000fffff')])
T=np.array([list('ffffffffff'),list('fffffffff0'),list('ffffffff00'),list('fffffff000'),list('ffffff0000'),list('ffffffffff'),list('ffff00ffff'),list('fff0000fff'),list('ff000000ff'),list('f00000000f')])
for k in range(4):
 for flip in [False,True]:
  A=np.rot90(D,k)
  if flip:A=np.fliplr(A)
  if np.array_equal(A,T):print(k,flip)
  C=np.where(A=='f','0','f')
  if np.array_equal(C,T):print('comp',k,flip)
print('T\n',T)
print('transpose D complement\n',np.where(D.T=='f','0','f'))
